import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { getSession } from "@/lib/auth";

export async function GET() {
  const session = await getSession();
  if (!session) return NextResponse.json({ error: "Chưa đăng nhập" }, { status: 401 });

  const role = session.roleId;
  let stats: any = {};
  let recent: any[] = [];
  let notifications: any[] = [];

  notifications = await db.notification.findMany({
    where: { recipientUserId: session.userId },
    orderBy: { createdAt: "desc" },
    take: 5,
  });

  if (role === "CUSTOMER") {
    const horses = await db.horse.count({ where: { ownerUserId: session.userId } });
    const allCustomerRequests = await db.transportRequest.findMany({
      where: { customerId: session.userId },
      include: { origin: true, destination: true, horses: { include: { horse: true } }, invoices: true },
      orderBy: { createdAt: "desc" },
    });
    const requests = allCustomerRequests.slice(0, 5);
    const byStatus = await db.transportRequest.groupBy({
      by: ["status"],
      where: { customerId: session.userId },
      _count: true,
    });

    // Analytics: spending over time (last 6 months) from invoices
    const now = new Date();
    const sixMonthsAgo = new Date(now.getFullYear(), now.getMonth() - 5, 1);
    const invoices = await db.invoice.findMany({
      where: { request: { customerId: session.userId }, issuedAt: { gte: sixMonthsAgo } },
      include: { request: true },
    });
    const spendingByMonth: { month: string; amount: number }[] = [];
    for (let i = 5; i >= 0; i--) {
      const m = new Date(now.getFullYear(), now.getMonth() - i, 1);
      const next = new Date(now.getFullYear(), now.getMonth() - i + 1, 1);
      const inMonth = invoices.filter((inv) => inv.issuedAt >= m && inv.issuedAt < next);
      spendingByMonth.push({
        month: m.toLocaleDateString("vi-VN", { month: "short" }),
        amount: inMonth.reduce((s, inv) => s + inv.amount, 0),
      });
    }

    // Analytics: requests by status for pie chart
    const requestsByStatus = byStatus.map((g) => ({ name: g.status, value: g._count }));

    // Analytics: total spent + pending payment
    const totalSpent = invoices.filter((i) => i.paymentStatus === "Đã thanh toán").reduce((s, i) => s + i.amount, 0);
    const pendingPayment = allCustomerRequests.flatMap((r) => r.invoices).filter((i) => i.paymentStatus !== "Đã thanh toán").reduce((s, i) => s + i.amount, 0);

    // Analytics: horse transport count
    const horseTransportCount = await db.transportRequestHorse.groupBy({
      by: ["horseId"],
      where: { request: { customerId: session.userId } },
      _count: { horseId: true },
    });

    // Analytics: spending breakdown by competition (top 5)
    const spendingByCompetition = allCustomerRequests.map((r) => ({
      name: r.competitionName || `Đơn #${r.requestId.slice(-8)}`,
      amount: r.invoices.reduce((s, i) => s + i.amount, 0),
      status: r.status,
    })).filter((r) => r.amount > 0).sort((a, b) => b.amount - a.amount).slice(0, 5);

    stats = { horses, totalRequests: allCustomerRequests.length, byStatus, spendingByMonth, requestsByStatus, totalSpent, pendingPayment, horseTransportCount: horseTransportCount.length, spendingByCompetition };
    recent = requests;
  } else if (role === "TRANSPORT_SPECIALIST") {
    const pending = await db.transportRequest.count({ where: { status: { in: ["Đã gửi", "Đang thẩm định"] } } });
    const inspections = await db.inspectionStatus.count({ where: { assignedSpecialistId: session.userId, status: { in: ["Chờ kiểm tra", "Đang kiểm tra", "Cần bổ sung"] } } });
    const docsPending = await db.horseDocument.count({ where: { reviewStatus: { in: ["Đã nộp", "Đang kiểm tra"] } } });
    const requests = await db.transportRequest.findMany({
      where: { status: { in: ["Đã gửi", "Đang thẩm định", "Trả lại bổ sung"] } },
      include: { customer: true, origin: true, destination: true, horses: { include: { horse: true } } },
      orderBy: { createdAt: "desc" },
      take: 5,
    });
    stats = { pendingReview: pending, activeInspections: inspections, docsPending, total: requests.length };
    recent = requests;
  } else if (role === "LOGISTICS_MANAGER") {
    const pendingApproval = await db.transportRequest.count({ where: { status: "Đang thẩm định" } });
    const approved = await db.transportRequest.count({ where: { status: "Đã phê duyệt" } });
    const incidents = await db.incident.count({ where: { status: { in: ["Mới", "Đang xử lý"] } } });
    const activeTrips = await db.transportPlan.count({ where: { status: "Đang thực hiện" } });
    const staff = await db.user.count({ where: { roleId: { not: "ADMIN" } } });
    const requests = await db.transportRequest.findMany({
      where: { status: { in: ["Đang thẩm định", "Đã gửi"] } },
      include: { customer: true, origin: true, destination: true },
      orderBy: { createdAt: "desc" },
      take: 5,
    });

    // Analytics: requests by status
    const statusGroups = await db.transportRequest.groupBy({ by: ["status"], _count: true });
    const requestsByStatus = statusGroups.map((g) => ({ name: g.status, value: g._count }));

    // Analytics: monthly volume (last 6 months)
    const now = new Date();
    const sixMonthsAgo = new Date(now.getFullYear(), now.getMonth() - 5, 1);
    const allRequests = await db.transportRequest.findMany({
      where: { createdAt: { gte: sixMonthsAgo } },
      select: { createdAt: true, status: true, estimatedAmount: true },
    });
    const monthlyVolume: { month: string; requests: number; revenue: number }[] = [];
    for (let i = 5; i >= 0; i--) {
      const m = new Date(now.getFullYear(), now.getMonth() - i, 1);
      const next = new Date(now.getFullYear(), now.getMonth() - i + 1, 1);
      const inMonth = allRequests.filter((r) => r.createdAt >= m && r.createdAt < next);
      monthlyVolume.push({
        month: m.toLocaleDateString("vi-VN", { month: "short" }),
        requests: inMonth.length,
        revenue: inMonth.reduce((s, r) => s + (r.estimatedAmount || 0), 0),
      });
    }

    // Analytics: revenue by currency
    const invoices = await db.invoice.findMany({ select: { amount: true, currency: true, paymentStatus: true } });
    const totalRevenue = invoices.filter((i) => i.paymentStatus === "Đã thanh toán").reduce((s, i) => s + i.amount, 0);
    const pendingRevenue = invoices.filter((i) => i.paymentStatus !== "Đã thanh toán").reduce((s, i) => s + i.amount, 0);

    stats = { pendingApproval, approved, incidents, activeTrips, staff, requestsByStatus, monthlyVolume, totalRevenue, pendingRevenue };
    recent = requests;
  } else if (role === "FLEET_COORDINATOR") {
    const approvedNoPlan = await db.transportRequest.count({ where: { status: "Đã phê duyệt", plans: { none: {} } } });
    const planning = await db.transportPlan.count({ where: { status: "Đang lập kế hoạch" } });
    const active = await db.transportPlan.count({ where: { status: { in: ["Sẵn sàng", "Đang thực hiện"] } } });
    const assets = await db.transportAsset.count();
    const readyAssets = await db.transportAsset.count({ where: { status: "Sẵn sàng" } });
    const plans = await db.transportPlan.findMany({
      include: { request: { include: { customer: true, origin: true, destination: true } } },
      orderBy: { departureTime: "desc" },
      take: 5,
    });

    // Analytics: plan status distribution
    const planStatusGroups = await db.transportPlan.groupBy({ by: ["status"], _count: true });
    const plansByStatus = planStatusGroups.map((g) => ({ name: g.status, value: g._count }));

    // Analytics: asset utilization (assets grouped by status)
    const assetStatusGroups = await db.transportAsset.groupBy({ by: ["status"], _count: true });
    const assetsByStatus = assetStatusGroups.map((g) => ({ name: g.status, value: g._count }));

    // Analytics: trip volume by month (last 6 months)
    const now = new Date();
    const sixMonthsAgo = new Date(now.getFullYear(), now.getMonth() - 5, 1);
    const allPlans = await db.transportPlan.findMany({
      where: { departureTime: { gte: sixMonthsAgo } },
      select: { departureTime: true, status: true },
    });
    const tripVolume: { month: string; trips: number }[] = [];
    for (let i = 5; i >= 0; i--) {
      const m = new Date(now.getFullYear(), now.getMonth() - i, 1);
      const next = new Date(now.getFullYear(), now.getMonth() - i + 1, 1);
      const inMonth = allPlans.filter((p) => p.departureTime >= m && p.departureTime < next);
      tripVolume.push({ month: m.toLocaleDateString("vi-VN", { month: "short" }), trips: inMonth.length });
    }

    stats = { approvedNoPlan, planning, active, assets, readyAssets, plansByStatus, assetsByStatus, tripVolume };
    recent = plans;
  } else if (role === "DRIVER_ESCORT") {
    const myAssignments = await db.transportAssignment.findMany({
      where: { OR: [{ driverUserId: session.userId }, { attendantUserId: session.userId }] },
      include: { plan: { include: { request: { include: { origin: true, destination: true, horses: { include: { horse: true } } } } } } },
      orderBy: { assignedAt: "desc" },
    });
    const active = myAssignments.filter((a) => ["Sẵn sàng", "Đang thực hiện"].includes(a.plan.status));
    stats = { totalAssignments: myAssignments.length, active: active.length };
    recent = myAssignments.map((a) => a.plan);
  }

  return NextResponse.json({ role, stats, recent, notifications });
}
